/** Job constants, row shape, JSON mapping, and request validation shared by the server and worker. */

export const MAX_ATTEMPTS = 3;
export const STEP_MS = 100;
export const RETRY_DELAY_MS = 500;
export const HEARTBEAT_INTERVAL_MS = 1_000;
export const HEARTBEAT_STALE_MS = 3_000;
export const TRANSIENT_ERROR = 'transient failure';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as selected with `SELECT *`. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  run_after: number;
  created_at: string;
  updated_at: string;
}

export interface FieldError {
  field: string;
  message: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export type ValidationResult = { ok: true; job: NewJob } | { ok: false; fields: FieldError[] };

export function jobToJson(row: JobRow) {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

const FIELD_NAMES: readonly string[] = ['input', 'steps', 'failAttempts'];

const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function integerField(body: Record<string, unknown>, name: string, min: number, max: number, dflt: number, fields: FieldError[]): number {
  const v = body[name];
  if (v === undefined) return dflt;
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return dflt;
  }
  return v;
}

/** Validates a parsed request body and applies defaults. Collects every offending field. */
export function validateJobBody(body: unknown): ValidationResult {
  if (!isPlainObject(body)) return { ok: false, fields: [{ field: 'body', message: 'must be a JSON object' }] };
  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!FIELD_NAMES.includes(key)) fields.push({ field: key, message: 'unknown field' });
  }
  const input = body.input;
  let inputValue = '';
  if (input === undefined) {
    fields.push({ field: 'input', message: 'is required' });
  } else if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'must be a string' });
  } else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  } else if (input.trim() === '') {
    fields.push({ field: 'input', message: 'must not be only whitespace' });
  } else {
    inputValue = input;
  }
  const steps = integerField(body, 'steps', 1, 20, 5, fields);
  const failAttempts = integerField(body, 'failAttempts', 0, 5, 0, fields);
  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, job: { input: inputValue, steps, failAttempts } };
}

