import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { inTransaction, openDatabase } from './db.ts';
import {
  HEARTBEAT_STALE_MS,
  jobToJson,
  validateJobBody,
  type FieldError,
  type JobRow,
  type NewJob,
} from './jobs.ts';

const MAX_BODY_BYTES = 64 * 1024;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const insertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, run_after, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
);
const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const selectHeartbeat = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id = 1');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function errorBody(code: string, message: string, fields?: FieldError[]) {
  return { error: fields ? { code, message, fields } : { code, message } };
}

function notFound(res: ServerResponse): void {
  send(res, 404, errorBody('not_found', 'No such route.'));
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  send(res, 405, errorBody('method_not_allowed', `Method not allowed. Allowed: ${allowed.join(', ')}.`), { allow: allowed.join(', ') });
}

function readBody(req: IncomingMessage): Promise<string | undefined> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? undefined : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function isJsonContentType(value: string | undefined): boolean {
  if (value === undefined) return false;
  const mediaType = value.split(';')[0]!.trim().toLowerCase();
  return mediaType === 'application/json' || mediaType.endsWith('+json');
}

type Parsed = { ok: true; job: NewJob; key: string | undefined } | { ok: false; fields: FieldError[] };

/** Checks headers and body together, so every problem is reported in one response. */
function parseCreateRequest(req: IncomingMessage, raw: string | undefined): Parsed {
  const fields: FieldError[] = [];
  const key = req.headers['idempotency-key'];
  if (key !== undefined && !IDEMPOTENCY_KEY_RE.test(key)) {
    fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }
  let job: NewJob | undefined;
  if (raw === undefined) {
    fields.push({ field: 'body', message: 'body is too large' });
  } else if (!isJsonContentType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else {
    let parsed: unknown;
    try {
      parsed = JSON.parse(raw);
    } catch {
      fields.push({ field: 'body', message: 'malformed JSON' });
      parsed = undefined;
    }
    if (fields.length === 0) {
      const result = validateJobBody(parsed);
      if (result.ok) job = result.job;
      else fields.push(...result.fields);
    }
  }
  if (fields.length > 0 || job === undefined) return { ok: false, fields };
  return { ok: true, job, key };
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const parsed = parseCreateRequest(req, await readBody(req));
  if (!parsed.ok) {
    send(res, 400, errorBody('invalid_request', 'The submission is invalid.', parsed.fields));
    return;
  }
  const { job, key } = parsed;
  const outcome = inTransaction(db, () => {
    if (key !== undefined) {
      const existing = selectByKey.get(key) as unknown as JobRow | undefined;
      if (existing) {
        const same =
          existing.input === job.input && existing.steps === job.steps && existing.fail_attempts === job.failAttempts;
        return same
          ? { status: 200, body: jobToJson(existing) }
          : { status: 409, body: errorBody('idempotency_conflict', 'This Idempotency-Key was already used for a different submission.') };
      }
    }
    const now = new Date().toISOString();
    const id = randomUUID();
    insertJob.run(id, job.input, job.steps, job.failAttempts, key ?? null, now, now);
    const row = selectById.get(id) as unknown as JobRow;
    return { status: 201, body: jobToJson(row) };
  });
  send(res, outcome.status, outcome.body);
}

function getJob(res: ServerResponse, rawId: string): void {
  let id = rawId;
  try {
    id = decodeURIComponent(rawId);
  } catch {
    // keep the raw segment; it will simply not match a job
  }
  const row = selectById.get(id) as unknown as JobRow | undefined;
  if (!row) {
    send(res, 404, errorBody('not_found', 'No such job.'));
    return;
  }
  send(res, 200, jobToJson(row));
}

function health(res: ServerResponse): void {
  const hb = selectHeartbeat.get() as unknown as { seen_at: number } | undefined;
  const up = hb !== undefined && Date.now() - hb.seen_at <= HEARTBEAT_STALE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? '';

  if (pathname === '/health') return method === 'GET' ? health(res) : methodNotAllowed(res, ['GET']);
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: (selectAll.all() as unknown as JobRow[]).map(jobToJson) });
    if (method === 'POST') return createJob(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method === 'GET') return getJob(res, match[1]!);
    return methodNotAllowed(res, ['GET']);
  }
  notFound(res);
}

const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) send(res, 500, errorBody('internal_error', 'Internal server error.'));
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    if (stopping) return;
    stopping = true;
    server.close(() => {
      db.close();
      process.exit(0);
    });
    server.closeAllConnections();
  });
}

