import { setTimeout as sleep } from 'node:timers/promises';
import { inTransaction, openDatabase } from './db.ts';
import {
  HEARTBEAT_INTERVAL_MS,
  MAX_ATTEMPTS,
  RETRY_DELAY_MS,
  STEP_MS,
  TRANSIENT_ERROR,
  type JobRow,
} from './jobs.ts';

const IDLE_POLL_MS = 200;

const db = openDatabase();
let stopping = false;

const now = () => new Date().toISOString();

const claimNext = db.prepare(
  "SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1",
);
const markRunning = db.prepare(
  "UPDATE jobs SET status = 'running', attempts = ?, progress_completed = 0, updated_at = ? WHERE seq = ?",
);
const setProgress = db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE seq = ?');
const requeue = db.prepare(
  "UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE seq = ?",
);
const finishCompleted = db.prepare(
  "UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE seq = ?",
);
const finishFailed = db.prepare(
  "UPDATE jobs SET status = 'failed', result_output = NULL, error = ?, attempts = ?, progress_completed = 0, updated_at = ? WHERE seq = ?",
);
const recoverRunning = db.prepare(
  "UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'",
);
const writeHeartbeat = db.prepare(
  'INSERT INTO worker_heartbeat (id, seen_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET seen_at = excluded.seen_at',
);

/** Requeues jobs left `running` by a previous worker that died or stopped mid-attempt. */
function recoverInterrupted(): void {
  inTransaction(db, () => recoverRunning.run(now()));
}

/** Claims the oldest eligible queued job and marks it as the next attempt. */
function claim(): JobRow | undefined {
  return inTransaction(db, () => {
    const row = claimNext.get(Date.now()) as unknown as JobRow | undefined;
    if (!row) return undefined;
    if (row.attempts >= MAX_ATTEMPTS) {
      // Only reachable after a crash during the final attempt: no attempts remain.
      finishFailed.run(TRANSIENT_ERROR, row.attempts, now(), row.seq);
      return undefined;
    }
    const attempt = row.attempts + 1;
    markRunning.run(attempt, now(), row.seq);
    return { ...row, status: 'running', attempts: attempt, progress_completed: 0 };
  });
}

/** Runs one attempt of a job that has already been marked running. */
async function runAttempt(job: JobRow): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    // Simulated transient failure: fails before any progress is made.
    if (job.attempts >= MAX_ATTEMPTS) finishFailed.run(TRANSIENT_ERROR, job.attempts, now(), job.seq);
    else requeue.run(Date.now() + RETRY_DELAY_MS, now(), job.seq);
    return;
  }
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      // Graceful stop mid-attempt: hand the job back so it is picked up again after restart.
      requeue.run(0, now(), job.seq);
      return;
    }
    setProgress.run(step, now(), job.seq);
  }
  finishCompleted.run(job.input.toUpperCase(), now(), job.seq);
}

/** Returns true if a job attempt was run (or a job was finalised), false if the queue was idle. */
async function processNext(): Promise<boolean> {
  const job = claim();
  if (!job) return false;
  await runAttempt(job);
  return true;
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

recoverInterrupted();
writeHeartbeat.run(Date.now());
const heartbeat = setInterval(() => writeHeartbeat.run(Date.now()), HEARTBEAT_INTERVAL_MS);

console.log('worker started');
while (!stopping) {
  const didWork = await processNext();
  if (!didWork && !stopping) await sleep(IDLE_POLL_MS);
}

clearInterval(heartbeat);
writeHeartbeat.run(0); // seen_at 0 is long past the staleness window, so health reports the worker down
db.close();
console.log('worker stopped');
process.exit(0);

